npx --yes tsx <<'EOF'
import { readFileSync } from 'node:fs';
import assert from 'node:assert/strict';
import { RoomPlanCaptureService } from './apps/api/src/index.ts';
const request = JSON.parse(readFileSync('./fixtures/roomplan/bedroom-primary/capture-request.json','utf8'));
const expected = JSON.parse(readFileSync('./fixtures/roomplan/bedroom-primary/scene.json','utf8'));
const service = new RoomPlanCaptureService({ now: () => new Date('2026-04-17T00:00:00Z'), token_secret: 'test-secret' });
const capture = service.postRoomPlanCapture(request);
const scene = service.getScene(capture.scene_id);
function normalize(v){
  if (v === null || typeof v !== 'object') return v;
  if (Array.isArray(v)) return v.map(normalize);
  const out = {};
  for (const [k,val] of Object.entries(v)) {
    if (k.endsWith('_at') || k === 'updated_at' || k === 'created_at' || k === 'expires_at' || k === 'redeemed_at' || k === 'used_at') out[k] = '<time>';
    else out[k] = normalize(val);
  }
  return out;
}
assert.deepStrictEqual(normalize(scene), normalize(expected));
console.log('scene parity ok');
EOF

